function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const reading = multisetDiff(before.reading, after.reading);
  const step = multisetDiff(before.step, after.step);
  return {
    rels: [
      { rel: "reading", add: reading.add, del: reading.del },
      { rel: "step", add: step.add, del: step.del },
    ],
    carryPending: step.add.length > 0 || step.del.length > 0 || reading.del.length > 0,
  };
}

